import { useParams } from "next/navigation"
import { AxiosError } from "axios"
import { toast } from "sonner"
import { useQueryClient, useMutation } from "@tanstack/react-query"
import { queryKeys } from "@/lib/query-keys"
import axiosInstance from "@/utils/axios"
import { getLocaleString } from "@/utils/getLocaleString"

export function usePreselectAdd() {
  const queryClient = useQueryClient()
  const params = useParams() as { locale: string }

  const lang = getLocaleString(params.locale)
  const queryKey = queryKeys.preselects(lang)

  const mutation = useMutation({
    mutationFn: async (course: {
      name: string
      semester: string
      serial: string
    }) => {
      const res = await axiosInstance.post("/v3/course-tables/preselected", {
        semester: course.semester,
        serial: course.serial,
      })
      return res.data
    },
    onMutate: async (course) => {
      // TODO: Add optimistic update
      const toastId = toast.loading(`${course.name} 加入中 ...`)
      return { course, toastId }
    },
    onError: (err, _, context) => {
      if (err instanceof AxiosError && err.response?.data.code)
        return toast.dismiss(context?.toastId)
      toast.error("加入課程失敗", { id: context?.toastId })
    },
    onSuccess: (_, __, context) => {
      toast.success(`${context?.course.name} 已加入預選課表`, {
        id: context?.toastId,
      })
    },
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey })
    },
  })

  return mutation
}

import { useLocale } from "next-intl"
import {
  useQuery,
  useQueryClient,
  type UseQueryResult,
} from "@tanstack/react-query"
import { useUser } from "@/queries/user"
import { queryKeys } from "@/lib/query-keys"
import { PreselectTable, PreselectTableFull } from "@/types/course-table"
import axiosInstance from "@/utils/axios"
import { getLocaleString } from "@/utils/getLocaleString"

// withCourse=true → 帶 course 的 Full 型別;withCourse=null → id-only 精簡型別
export function usePreselect(props: {
  withCourse: true
}): UseQueryResult<PreselectTableFull>
export function usePreselect(props: {
  withCourse: null
}): UseQueryResult<PreselectTable>
export function usePreselect({ withCourse }: { withCourse: true | null }) {
  const { data: user } = useUser()
  const locale = useLocale()
  const lang = getLocaleString(locale)
  const queryClient = useQueryClient()

  const query = useQuery({
    queryKey: withCourse
      ? queryKeys.preselects(lang)
      : queryKeys.preselectIds(lang),
    queryFn: async () => {
      const res = await axiosInstance.get(`/v3/course-tables/preselected`, {
        params: { withCourse, lang },
      })
      if (!withCourse) return PreselectTable.parse(res.data)
      const data = PreselectTableFull.parse(res.data)
      // withCourse 的回應已完整包含 id-only 那支的欄位(serial 等),抓到就同步
      // 鏡射進 id-only 快取:兩邊同一 tick 更新(ButtonPreselect 讀 id-only,不會
      // 慢一個 render),也省掉 id-only 自己再打一次請求。
      queryClient.setQueryData(queryKeys.preselectIds(lang), data)
      return data
    },
    enabled: !!user,
    staleTime: Infinity,
  })

  return query
}

"use client"

import { useMemo, useState } from "react"
import { useFormatter, useTranslations } from "next-intl"
import IntervalCell from "@/components/timetable/interval-cell"
import Timetable from "@/components/timetable/timetable"
import { getCourseColor } from "@/components/timetable/utils"
import { Link as NextLink } from "@/i18n/routing"
import { hrefMap } from "@/lib/href"
import { usePreselect } from "@/queries/preselect"
import type { Day, Interval } from "@/schema/schedule"
import { getAssignedMap } from "@/utils/preselect"
import { richValues } from "@/utils/richValues"

const intervals = "0123456789XABCD".split("") as Interval[]
const weekdays = [1, 2, 3, 4, 5, 6] as Day[]

export default function OverviewTimetable() {
  const t = useTranslations("schedule.table")
  const format = useFormatter()
  const { data, isLoading } = usePreselect({ withCourse: true })
  const [hovered, setHovered] = useState<string | null>(null)

  // 課表只顯示「已選上(assigned)+ 已登記(enrolled)」,待登記不顯示。
  const assignedMap = getAssignedMap(data?.assignedCourses || [])
  const enrolledMap = getAssignedMap(data?.enrolledCourses || [])

  const enrolledNotInSchedule = useMemo(
    () =>
      (
        data?.enrolledCourses?.filter(
          ({ course }) => course.schedules.length === 0
        ) || []
      ).map(({ course }) => course.name),
    [data]
  )

  const assignedNotInSchedule = useMemo(
    () =>
      (
        data?.assignedCourses?.filter(
          ({ course }) => course.schedules.length === 0
        ) || []
      ).map(({ course }) => course.name),
    [data]
  )

  return (
    <Timetable isLoading={isLoading}>
      {intervals.map((interval) => (
        <div key={interval} className="tr">
          <IntervalCell interval={interval} />
          {weekdays.map((day) => (
            <div key={day} className="td">
              {assignedMap[`${day}${interval}`]?.map(({ course }) => {
                const courseColor = getCourseColor(course)
                return (
                  <NextLink
                    href={hrefMap.course(course.semester, course.serial)}
                    key={course.id}
                    className="overflow-hidden rounded-r border-l-4 bg-white p-1 text-left text-sm whitespace-nowrap shadow transition-colors select-none"
                    style={{ borderColor: courseColor }}
                    onMouseEnter={() => setHovered(course.id)}
                    onMouseLeave={() => setHovered(null)}
                  >
                    <span className="hidden md:inline">{course.serial} </span>
                    {course.name}
                  </NextLink>
                )
              })}
              {enrolledMap[`${day}${interval}`]?.map(({ course }) => {
                const courseColor = getCourseColor(course)
                const href = hrefMap.course(course.semester, course.serial)

                return (
                  <NextLink
                    key={course.id}
                    href={href}
                    className="overflow-hidden rounded-r border-l-4 p-1 text-left text-sm whitespace-nowrap transition-colors select-none"
                    style={
                      hovered === course.id
                        ? {
                            borderColor: courseColor,
                            backgroundColor: courseColor,
                            color:
                              courseColor === "#6F6F6F" ||
                              courseColor === "#0A84FF"
                                ? "white"
                                : "black",
                          }
                        : {
                            borderColor: courseColor,
                            backgroundColor: `${courseColor}40`,
                          }
                    }
                    onMouseEnter={() => setHovered(course.id)}
                    onMouseLeave={() => setHovered(null)}
                  >
                    <span className="hidden md:inline">{course.serial} </span>
                    {course.name}
                  </NextLink>
                )
              })}
            </div>
          ))}
        </div>
      ))}
      {(assignedNotInSchedule.length > 0 ||
        enrolledNotInSchedule.length > 0) && (
        <p className="mx-2 mt-2 flex flex-col gap-1 text-sm md:mx-0">
          {assignedNotInSchedule.length > 0 && (
            <span>
              {t.rich("assigned-not-in-schedule", {
                ...richValues,
                course: format.list(assignedNotInSchedule),
                count: assignedNotInSchedule.length,
              })}
            </span>
          )}
          {enrolledNotInSchedule.length > 0 && (
            <span>
              {t.rich("enrolled-not-in-schedule", {
                ...richValues,
                course: format.list(enrolledNotInSchedule),
                count: enrolledNotInSchedule.length,
              })}
            </span>
          )}
        </p>
      )}
    </Timetable>
  )
}

import type { PropsWithChildren } from "react"
import { useTranslations } from "next-intl"
import { cn } from "@/utils/cn"

export default function Timetable({
  children,
  isLoading,
}: PropsWithChildren<{ isLoading?: boolean }>) {
  const t = useTranslations("schedule.table")

  return (
    <div
      className={cn(
        "py-4 transition-opacity md:px-4",
        // TODO: USE CLASS NAME TO PASS THIS
        isLoading && "opacity-50"
      )}
    >
      <div className="h-full w-full">
        <div className="tr">
          <div className="td">{/* EMPTY CELL */}</div>
          {Array.from({ length: 6 }, (_, i) => (
            <div key={i} className="td font-bold">
              {t("weekday", { day: i })}
            </div>
          ))}
        </div>
        {children}
      </div>
    </div>
  )
}

"use client"

import { useMemo, useState } from "react"
import { useFormatter, useTranslations } from "next-intl"
import { type Theme, useMediaQuery } from "@mui/material"
import IntervalCell from "@/components/timetable/interval-cell"
import Timetable from "@/components/timetable/timetable"
import { getCourseColor } from "@/components/timetable/utils"
import { Link as NextLink } from "@/i18n/routing"
import { hrefMap } from "@/lib/href"
import { usePreselect } from "@/queries/preselect"
import type { Day, Interval } from "@/schema/schedule"
import { type Time, getPreselectMap, getAssignedMap } from "@/utils/preselect"
import { richValues } from "@/utils/richValues"

const intervals = "0123456789XABCD".split("") as Interval[]
const weekdays = [1, 2, 3, 4, 5, 6] as Day[]

export default function OverviewTimetable() {
  const t = useTranslations("schedule.table")
  const format = useFormatter()
  const isMobile = !useMediaQuery((theme: Theme) => theme.breakpoints.up("md"))
  const { data, isLoading } = usePreselect({ withCourse: true })
  const { timeMap, courseMap } = useMemo(
    () => getPreselectMap(data?.preselectedCourses || []),
    [data]
  )
  const [hovered, setHovered] = useState<string | null>(null)

  const assignedMap = getAssignedMap(data?.assignedCourses || [])

  const preselectNotInSchedule = useMemo(
    () =>
      (
        data?.preselectedCourses?.filter(
          ({ course }) => course.schedules.length === 0
        ) || []
      ).map(({ course }) => course.name),
    [data]
  )

  const assignedNotInSchedule = useMemo(
    () =>
      (
        data?.assignedCourses?.filter(
          ({ course }) => course.schedules.length === 0
        ) || []
      ).map(({ course }) => course.name),
    [data]
  )

  return (
    <Timetable isLoading={isLoading}>
      {intervals.map((interval) => (
        <div key={interval} className="tr">
          <IntervalCell interval={interval} />
          {weekdays.map((day) => (
            <div key={day} className="td">
              {/* TODO: REFACTOR THESE */}
              {assignedMap[`${day}${interval}`]?.map(({ course }) => {
                const courseColor = getCourseColor(course)
                return (
                  <NextLink
                    href={hrefMap.course(course.semester, course.serial)}
                    key={course.id}
                    className="overflow-hidden rounded-r border-l-4 bg-white p-1 text-left text-sm whitespace-nowrap transition-colors select-none"
                    style={{ borderColor: courseColor }}
                    onMouseEnter={() => setHovered(course.id)}
                    onMouseLeave={() => setHovered(null)}
                  >
                    {!isMobile && course.serial} {course.name}
                  </NextLink>
                )
              })}
              {timeMap[`${day}${interval}` as Time]?.map(({ id }) => {
                const course = courseMap[id]
                const courseColor = getCourseColor(course)
                const href = hrefMap.course(course.semester, course.serial)

                return (
                  <NextLink
                    key={course.id}
                    href={href}
                    className="overflow-hidden rounded-r border-l-4 p-1 text-left text-sm whitespace-nowrap transition-colors select-none"
                    style={
                      hovered === course.id
                        ? {
                            borderColor: courseColor,
                            backgroundColor: courseColor,
                            color:
                              courseColor === "#6F6F6F" ||
                              courseColor === "#0A84FF"
                                ? "white"
                                : "black",
                          }
                        : {
                            borderColor: courseColor,
                            backgroundColor: `${courseColor}40`,
                          }
                    }
                    onMouseEnter={() => setHovered(course.id)}
                    onMouseLeave={() => setHovered(null)}
                  >
                    {!isMobile && course.serial} {course.name}
                  </NextLink>
                )
              })}
            </div>
          ))}
        </div>
      ))}
      {(assignedNotInSchedule.length > 0 ||
        preselectNotInSchedule.length > 0) && (
        <p className="mx-2 mt-2 flex flex-col gap-1 text-sm md:mx-0">
          {assignedNotInSchedule.length > 0 && (
            <span>
              {t.rich("assigned-not-in-schedule", {
                ...richValues,
                course: format.list(assignedNotInSchedule),
                count: assignedNotInSchedule.length,
              })}
            </span>
          )}
          {preselectNotInSchedule.length > 0 && (
            <span>
              {t.rich("preselect-not-in-schedule", {
                ...richValues,
                course: format.list(preselectNotInSchedule),
                count: preselectNotInSchedule.length,
              })}
            </span>
          )}
        </p>
      )}
    </Timetable>
  )
}

import { z } from "zod"
import { Course } from "@/schema/course"
import { Phase } from "@/types/phase"

export enum Field {
  Chinese = "chinese",
  ForeignLanguage = "foreign",
  Calculus = "calculus",
  Common = "common",
}

export const fields = { ...Field }

/**
 * 各學期開放的志願序領域:下學期(term 2)只有國文、一般科目;上學期四個都有。
 */
export function getFieldsForSemester(semester: string | undefined): Field[] {
  const term = semester?.split("-")[1]
  return term === "2"
    ? [Field.Chinese, Field.Common]
    : [Field.Chinese, Field.ForeignLanguage, Field.Calculus, Field.Common]
}

export const Collection = z.object({
  courseId: z.string(),
  course: Course.optional(),
})

export type Collection = z.infer<typeof Collection>

const FieldEnum = z.enum(Object.keys(Field) as [keyof typeof Field])
const PhaseEnum = z.enum(Object.keys(Phase) as [keyof typeof Phase])

// ---- id-only 精簡模式(withCourse=null):不含 course ----
// field 兩模式都會回,設 optional 只是為了容忍 useEnroll 樂觀更新的 builder。
// phase 只有 preselect 端點回、result 端點不回,故 optional。

export const Preselect = z.object({
  serial: z.string(),
  order: z.number(),
  field: FieldEnum.optional(),
})

export const Enrolled = z.object({
  serial: z.string(),
  order: z.number(),
  field: FieldEnum.optional(),
})

export const Assigned = z.object({
  serial: z.string(),
  field: FieldEnum.optional(),
  phase: PhaseEnum.optional(),
})

export const Unassigned = z.object({
  serial: z.string(),
  field: FieldEnum.optional(),
  phase: PhaseEnum.optional(),
  reason: z.string().nullable(),
})

export type Preselect = z.infer<typeof Preselect>
export type Enrolled = z.infer<typeof Enrolled>
export type Assigned = z.infer<typeof Assigned>
export type Unassigned = z.infer<typeof Unassigned>

// ---- withCourse=true:base + 必帶 course ----

export const PreselectFull = Preselect.extend({ course: Course })
export const EnrolledFull = Enrolled.extend({ course: Course })
export const AssignedFull = Assigned.extend({ course: Course })
export const UnassignedFull = Unassigned.extend({ course: Course })

export type PreselectFull = z.infer<typeof PreselectFull>
export type EnrolledFull = z.infer<typeof EnrolledFull>
export type AssignedFull = z.infer<typeof AssignedFull>
export type UnassignedFull = z.infer<typeof UnassignedFull>

// ---- tables ----

export const PreselectTable = z.object({
  // 當階段未登記課程
  preselectedCourses: Preselect.array(),
  // 當階段已登記課程
  enrolledCourses: Enrolled.array(),
  // 上階段已選上
  assignedCourses: Assigned.array(),
  // 上階段未選上
  unassignedCourses: Unassigned.array(),
})

export const PreselectTableFull = z.object({
  preselectedCourses: PreselectFull.array(),
  enrolledCourses: EnrolledFull.array(),
  assignedCourses: AssignedFull.array(),
  unassignedCourses: UnassignedFull.array(),
})

export type PreselectTable = z.infer<typeof PreselectTable>
export type PreselectTableFull = z.infer<typeof PreselectTableFull>

// result 端點一律 withCourse=true → 用 Full
export const ResultTable = z.object({
  // 當階段未選上
  unassignedCourses: UnassignedFull.array(),
  // 當階段已選上
  assignedCourses: AssignedFull.array(),
})

export type ResultTable = z.infer<typeof ResultTable>

