"use client"

import { useMemo, useRef, useState } from "react"
import { useTranslations } from "next-intl"
import { parseAsStringEnum, useQueryState } from "nuqs"
import { move } from "@dnd-kit/helpers"
import { DragDropProvider } from "@dnd-kit/react"
import { Button } from "@/components/ui/button"
import { useSyncLocalStorage } from "@/hooks/sync-local-storage"
import { useAddDropRegister } from "@/mutations/add-drop-register"
import { useEnroll } from "@/mutations/enroll"
import { usePreselect } from "@/queries/preselect"
import { useProgress } from "@/queries/progress"
import type { Course } from "@/schema/course"
import { Field, fields } from "@/types/course-table"
import { Status } from "@/types/phase"
import { AddDropRegisterDialog } from "./add-drop-register-dialog"
import { PriorityAddDropRow } from "./priority-add-drop-row"
import { PriorityAssignedRow } from "./priority-assigned-row"
import { GRID_TEMPLATE } from "./priority-grid"
import { ContainerVerticalModifier } from "./priority-list-modifier"
import { PriorityListRow } from "./priority-list-row"
import {
  AddDropLabel,
  OrderedEmptyOverlay,
  OrderedFiller,
  OrderedLabel,
  PendingEmpty,
  PendingLabel,
} from "./priority-list-sections"
import { cleanReason, SubmitResultDialog } from "./submit-result-dialog"
import {
  PENDING_LABEL_ID,
  usePriorityItems,
  type PriorityDraft,
} from "./use-priority-items"

export default function PriorityList() {
  const t = useTranslations("schedule.priority-list")
  const tf = useTranslations("schedule.field-list")

  const [activeField] = useQueryState(
    "field",
    parseAsStringEnum(Object.values(Field)).withDefault(Field.Common)
  )

  const { data, isLoading } = usePreselect({ withCourse: true })
  const { data: progressData, isLoading: progressLoading } = useProgress()
  const status = progressData?.progress?.status
  const isActive = status === Status.Preselecting || status === Status.Started
  const isPreselecting = status === Status.Preselecting
  const isAddDrop =
    progressData?.progress?.phase?.startsWith("AddDrop") ?? false
  // 初選走 /v3/enroll;加退選三類批量走 /v3/add-drop/register(見 useEnroll)。
  const enroll = useEnroll({ addDrop: isAddDrop })
  const addDropRegister = useAddDropRegister()
  const [draftRaw, setDraftValue] = useSyncLocalStorage<PriorityDraft>(
    "priority-draft",
    {}
  )
  const draft = draftRaw ?? {}
  const [editingField, setEditingField] = useState<Field | null>(null)
  const isEditing = !!draft[activeField] || activeField === editingField
  const [dialogOpen, setDialogOpen] = useState(false)
  const [submittedAt, setSubmittedAt] = useState<Date | null>(null)
  const [failed, setFailed] = useState<{ courseId: string; reason: string }[]>(
    []
  )
  // 正在拖的課(serial),用來讓已登記空狀態 overlay 扣掉「拖進來但還沒 drop」的課。
  const [draggingId, setDraggingId] = useState<string | null>(null)
  // 加退選一 / 二類加選:點加選鈕先開對話框(一類確認、二類輸入授權碼),確認才送出。
  const [addDropTarget, setAddDropTarget] = useState<Course | null>(null)

  const orderedCourses = useMemo(
    () =>
      (data?.enrolledCourses ?? [])
        .filter((c) => fields[c.field!] === activeField)
        .sort((a, b) => a.order - b.order)
        .map((c) => c.course),
    [data, activeField]
  )

  const pendingCourses = useMemo(
    () =>
      (data?.preselectedCourses ?? [])
        .filter((c) => fields[c.field!] === activeField)
        .sort((a, b) => a.order - b.order)
        .map((c) => c.course),
    [data, activeField]
  )

  // 加退選:一 / 二類加選課獨立成「待加選」section(不參與拖曳),類別排序(一 → 二),
  // 同類維持原順序。三類留在待登記走拖曳。
  const addDropCourses = useMemo(
    () =>
      isAddDrop
        ? pendingCourses
            .filter((c) => c.enrollMethod === 1 || c.enrollMethod === 2)
            .sort((a, b) => (a.enrollMethod ?? 0) - (b.enrollMethod ?? 0))
        : [],
    [isAddDrop, pendingCourses]
  )

  // 已選上(上一階段分發結果):純顯示於「已登記」上方,不參與拖曳。
  const assignedCourses = useMemo(
    () =>
      (data?.assignedCourses ?? [])
        .filter((c) => fields[c.field!] === activeField)
        .map((c) => c.course),
    [data, activeField]
  )

  // 已選上的 serial 集合 —— 一 / 二類加選成功後仍留在待加選(preselectedCourses),
  // 用來把待加選列的「加選」鈕停用,避免對已選上的課重複加選。
  const assignedSerials = useMemo(
    () => new Set((data?.assignedCourses ?? []).map((c) => c.course.serial)),
    [data]
  )

  const courseMap = useMemo(
    () =>
      new Map([...orderedCourses, ...pendingCourses].map((c) => [c.serial, c])),
    [orderedCourses, pendingCourses]
  )

  const courseNameById = useMemo(() => {
    const map = new Map<string, string>()
    const add = (list?: { course?: { id: string; name: string } }[]) =>
      list?.forEach((c) => {
        if (c.course) map.set(c.course.id, c.course.name)
      })
    add(data?.enrolledCourses)
    add(data?.preselectedCourses)
    add(data?.assignedCourses)
    return map
  }, [data])

  // 上次送出時登記失敗的原因(courseId → 已清掉英文前綴的原因),直接顯示在課名下方。
  // 沿用 dialog 那份 failed state,不需另外存;重整頁面才會消失(和 dialog 一致)。
  const failReasonById = useMemo(
    () => new Map(failed.map((f) => [f.courseId, cleanReason(f.reason)])),
    [failed]
  )

  const {
    items,
    setItems,
    previousItems,
    isDirty,
    reset,
    onMoveToPending,
    onMoveToOrdered,
    onMoveToOrderedAt,
    onReorderInSection,
  } = usePriorityItems(
    activeField,
    orderedCourses,
    pendingCourses,
    draft,
    setDraftValue,
    !!data,
    isAddDrop
  )

  const hasChanges = isDirty || Object.keys(draft).length > 0

  const labelIndex = items.indexOf(PENDING_LABEL_ID)
  const orderedIds = items.slice(0, labelIndex)
  const pendingIds = items.slice(labelIndex + 1)

  // 已登記空狀態:扣掉正在拖進來的那門課 —— 拖進來時提示留著、拖出去時立刻出現。
  const showOrderedEmpty =
    orderedIds.length -
      (draggingId && orderedIds.includes(draggingId) ? 1 : 0) ===
    0

  // enroll 是全量覆蓋,送出時帶「所有 field」:當前 field 用最新 items、其他 field
  // 用草稿(若有),沒草稿的 field 用 server 現狀,避免清掉別領域的登記。
  const buildSubmitSerials = (kind: "ordered" | "pending") => {
    const source =
      kind === "ordered" ? data?.enrolledCourses : data?.preselectedCourses
    return Object.values(Field).flatMap((field) => {
      const d = field === activeField ? items : draft[field]
      let base: string[]
      if (d && d.length > 1) {
        const lblIdx = d.indexOf(PENDING_LABEL_ID)
        base = kind === "ordered" ? d.slice(0, lblIdx) : d.slice(lblIdx + 1)
      } else {
        base = (source ?? [])
          .filter((c) => fields[c.field!] === field)
          .sort((a, b) => a.order - b.order)
          .map((c) => c.course.serial)
      }
      // 加退選:一 / 二類加選課不在拖曳序列(在待加選 section),送出待登記時要補回
      // preselectedSerials,否則「儲存」會把它們從待登記清掉。
      if (kind === "pending" && isAddDrop) {
        const addTypes = (data?.preselectedCourses ?? [])
          .filter((c) => fields[c.field!] === field)
          .filter(
            (c) => c.course.enrollMethod === 1 || c.course.enrollMethod === 2
          )
          .map((c) => c.course.serial)
          .filter((s) => !base.includes(s))
        base = [...base, ...addTypes]
      }
      return base
    })
  }

  // 拖曳限制:只能垂直移動,並夾在已登記 / 待登記區塊範圍內。
  const containerRef = useRef<HTMLDivElement>(null)
  const modifier = useMemo(
    () =>
      ContainerVerticalModifier.configure({
        getRect: () => {
          const container =
            containerRef.current?.getBoundingClientRect() ?? null
          if (!container) return null
          // 預選階段已登記鎖定:把待登記課程的拖曳夾在「待登記」標籤下方,
          // 不讓它滑過標籤進到已登記區。
          if (isPreselecting) {
            const label = containerRef.current
              ?.querySelector("[data-pending-label]")
              ?.getBoundingClientRect()
            if (label)
              return new DOMRect(
                container.x,
                label.bottom,
                container.width,
                container.bottom - label.bottom
              )
          }
          return container
        },
      }),
    [isPreselecting]
  )

  // Gate on every query the content branches read (preselect data + progress).
  if (isLoading || progressLoading || !progressData) {
    return (
      <div className="border-t bg-white p-8 text-center opacity-50">
        {tf("loading")}
      </div>
    )
  }

  const rowProps = {
    isActive,
    isPreselecting,
    isEditing,
    failReasonById,
    onEnterEdit: () => setEditingField(activeField),
    onReorderInSection,
    onMoveToPending,
    onMoveToOrdered,
    onMoveToOrderedAt,
  }

  return (
    <div className="flex flex-col tabular-nums">
      <DragDropProvider
        modifiers={[modifier]}
        onDragStart={(event) => {
          setDraggingId(String(event.operation.source?.id ?? "") || null)
          previousItems.current = items
          if (!isEditing) setEditingField(activeField)
        }}
        onDragOver={(event) => {
          // 原生 sortable:即時把新順序寫回,讓 React 與 dnd-kit 的 DOM 始終一致
          // (避免只在 onDragEnd 更新造成的 removeChild / useInsertionEffect 爆錯)。
          setItems((prev) => {
            if (!isActive) return prev
            const next = move(prev, event)
            // 預選階段:已登記鎖定,不能把課從待登記移進已登記。
            if (isPreselecting) {
              const srcId = String(event.operation.source?.id ?? "")
              const lbl = (arr: string[]) => arr.indexOf(PENDING_LABEL_ID)
              const wasPending = prev.indexOf(srcId) > lbl(prev)
              const nowOrdered = next.indexOf(srcId) < lbl(next)
              if (wasPending && nowOrdered) return prev
            }
            return next
          })
        }}
        onDragEnd={(event) => {
          setDraggingId(null)
          if (event.canceled) setItems(previousItems.current)
        }}
      >
        <div className="overflow-x-auto bg-white">
          <div className="min-w-[58.625rem]">
            {/* header */}
            <div
              style={{ gridTemplateColumns: GRID_TEMPLATE }}
              className="grid bg-muted text-sm text-muted-foreground [&>*]:px-2 [&>*]:py-2 [&>*]:whitespace-nowrap"
            >
              <div className="text-center">{t("preference-order")}</div>
              <div className="text-left">{t("serial-number")}</div>
              <div className="text-left">{t("course-name")}</div>
              <div className="text-left">{t("instructor")}</div>
              <div className="text-right">{t("credits")}</div>
              <div className="text-left">{t("class-time")}</div>
              <div className="text-right">{t("enrollment-limit")}</div>
              <div className="text-right">{t("enrolled")}</div>
              <div className="text-right">{t("registered")}</div>
              <div className="text-right"></div>
            </div>

            {/* 已選上 —— 靜態,不參與拖曳 */}
            {assignedCourses.map((course) => (
              <PriorityAssignedRow key={course.serial} course={course} />
            ))}

            {/* 已登記 */}
            <OrderedLabel
              label={
                isAddDrop ? t("ordered-section-add-drop") : t("ordered-section")
              }
            />
            {/* 單一容器:所有 sortable 課程列與填充 / 標籤都是同一個 DOM parent 的
                兄弟,拖到別區塊時才不會跨容器搬 DOM 而爆錯。拖曳也夾在此範圍。 */}
            <div ref={containerRef} className="relative">
              {showOrderedEmpty && (
                <OrderedEmptyOverlay
                  canDrop={isActive && !isPreselecting}
                  opensAt={progressData?.progress?.endAt}
                  line1={t("ordered-empty-line1")}
                  line2={t("ordered-empty-line2")}
                  active={!!draggingId && orderedIds.includes(draggingId)}
                />
              )}
              {orderedIds.map((serial, sectionIndex) => {
                const course = courseMap.get(serial)
                if (!course) return null
                return (
                  <PriorityListRow
                    key={serial}
                    course={course}
                    flatIndex={sectionIndex}
                    sectionIndex={sectionIndex}
                    section="ordered"
                    isFirstInSection={sectionIndex === 0}
                    isLastInSection={sectionIndex === orderedIds.length - 1}
                    {...rowProps}
                  />
                )
              })}
              <OrderedFiller rowCount={orderedIds.length} />

              {/* 待登記(sentinel:分界 + 隨拖曳 reflow) */}
              <PendingLabel
                label={
                  isAddDrop
                    ? t("pending-section-add-drop")
                    : t("pending-section")
                }
                index={labelIndex}
                locked={isPreselecting}
              />
              {pendingIds.length === 0 && (
                <PendingEmpty
                  label={t("pending-empty")}
                  searchLabel={t("pending-empty-search")}
                />
              )}
              {pendingIds.map((serial, sectionIndex) => {
                const course = courseMap.get(serial)
                if (!course) return null
                return (
                  <PriorityListRow
                    key={serial}
                    course={course}
                    flatIndex={labelIndex + 1 + sectionIndex}
                    sectionIndex={sectionIndex}
                    section="pending"
                    isFirstInSection={sectionIndex === 0}
                    isLastInSection={sectionIndex === pendingIds.length - 1}
                    {...rowProps}
                  />
                )
              })}
            </div>

            {/* 待加選 —— 加退選一 / 二類,用按鈕加選,不參與拖曳 */}
            {addDropCourses.length > 0 && (
              <>
                <AddDropLabel label={t("add-drop-section")} />
                {addDropCourses.map((course) => (
                  <PriorityAddDropRow
                    key={course.serial}
                    course={course}
                    isActive={isActive}
                    isEditing={isEditing}
                    isAssigned={assignedSerials.has(course.serial)}
                    addDropPending={addDropRegister.isPending}
                    failReason={failReasonById.get(course.id)}
                    onRequestAddDrop={(c) => setAddDropTarget(c)}
                  />
                ))}
              </>
            )}
          </div>
        </div>
      </DragDropProvider>

      <div className="sticky bottom-0 z-10 -mt-px flex items-center justify-end gap-2 border-t bg-white p-2">
        {isEditing ? (
          <>
            <Button
              key="cancel-edit"
              variant="outline"
              onClick={() => {
                reset()
                setEditingField(null)
              }}
              // 有更動 → 還原編輯(丟掉本地未儲存草稿);沒更動 → 取消編輯(單純退出)。
              // 兩者都是純本地零風險,任何階段都可點,不然沒動過就退不出編輯模式。
            >
              {hasChanges ? t("cancel-edit") : t("exit-edit")}
            </Button>
            <Button
              key="submit"
              onClick={() =>
                enroll.mutate(
                  {
                    serials: buildSubmitSerials("ordered"),
                    preselectedSerials: buildSubmitSerials("pending"),
                  },
                  {
                    onSuccess: (result) => {
                      setEditingField(null)
                      setSubmittedAt(new Date())
                      setFailed(result.failed)
                      setDialogOpen(true)
                      setDraftValue({})
                    },
                  }
                )
              }
              disabled={enroll.isPending || !isActive || !hasChanges}
            >
              {t("submit")}
            </Button>
          </>
        ) : (
          <Button
            key="edit-priority"
            // 預選階段整頁鎖定,無法編輯 → 停用「編輯志願序」(保留按鈕、不整個拿掉)。
            onClick={() => setEditingField(activeField)}
            disabled={!isActive || isPreselecting}
          >
            {t("edit-priority")}
          </Button>
        )}
      </div>

      <SubmitResultDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        submittedAt={submittedAt}
        failed={failed}
        courseName={(id) => courseNameById.get(id) ?? id}
      />

      <AddDropRegisterDialog
        course={addDropTarget}
        open={!!addDropTarget}
        onOpenChange={(o) => !o && setAddDropTarget(null)}
        pending={addDropRegister.isPending}
        onConfirm={(authCode) => {
          if (!addDropTarget) return
          addDropRegister.mutate(
            { serial: addDropTarget.serial, authCode },
            { onSettled: () => setAddDropTarget(null) }
          )
        }}
      />
    </div>
  )
}
